std::vector<int> v(100);

// operator[] is syntactic sugar for pointer arithmetic
// Highly optimized, direct memory access.
int* raw_ptr = v.data();

// Access 1: Standard operator[] (Unchecked)
int val_op = v[50];

// Access 2: Direct pointer arithmetic (Equivalent)
int val_ptr = *(raw_ptr + 50);

// IMPLICATION: Programmer MUST ensure validity.
// Failure results in Undefined Behavior (UB).
v[v.size() + 1] = 42; // UB - Memory corruption likely.

// Alternative: v.at(index) provides bounds checking.
// Slower due to runtime check, offers safety (throws std::out_of_range).
